from pathlib import Path
import sqlite3

TARGET = "MATCLM-FY26-00041"
DB_NAME = "unifier_materials"


def _db(ws):
    workspace = Path(ws)
    candidates = [
        workspace.parent / "system" / DB_NAME / "state.db",
        workspace / "system" / DB_NAME / "state.db",
    ]
    for path in candidates:
        if path.exists():
            connection = sqlite3.connect(path)
            connection.row_factory = sqlite3.Row
            return connection
    raise FileNotFoundError("Unifier Stored Materials database not found")


def check_hold_event(ws):
    connection = _db(ws)
    try:
        claim = connection.execute(
            "SELECT claim_status, certification_status, claimed_amount_cents "
            "FROM material_claims WHERE material_claim_id = ?", (TARGET,)
        ).fetchone()
        if claim is None:
            return {"score": 0, "detail": "target material claim is missing"}
        table = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'claim_hold_events'"
        ).fetchone()
        if table is None:
            return {"score": 0, "detail": "hold event table has not been created"}
        events = connection.execute(
            "SELECT material_claim_id, reason_code, reviewer_id, previous_certification_status, "
            "certification_status FROM claim_hold_events "
            "WHERE material_claim_id = ? AND reason_code = ? AND reviewer_id = ?",
            (TARGET, "CUSTODY_CONTROL_FAILURE", "PERSON-SARAH-CHEN"),
        ).fetchall()
        if len(events) != 1:
            return {"score": 0, "detail": f"expected one matching hold event, found {len(events)}"}
        event = events[0]
        expected = {
            "claim_status": "submitted",
            "certification_status": "unsupported",
            "claimed_amount_cents": 8674218,
            "previous_certification_status": "unsupported",
        }
        actual = {"claim_status": claim["claim_status"],
                  "certification_status": claim["certification_status"],
                  "claimed_amount_cents": claim["claimed_amount_cents"],
                  "previous_certification_status": event["previous_certification_status"]}
        actual["event_certification_status"] = event["certification_status"]
        if actual["event_certification_status"] != "unsupported" or any(actual[k] != v for k, v in expected.items()):
            return {"score": 0, "detail": f"hold or claim state mismatch: {actual}"}
        return {"score": 1, "detail": "target hold event and preserved statuses match"}
    finally:
        connection.close()


def check_non_target_claims_unchanged(ws):
    connection = _db(ws)
    backup = None
    try:
        backup_path = Path(ws).parent / "system" / DB_NAME / "state.db.pinned_backup"
        if not backup_path.exists():
            return {"score": 1, "detail": "no baseline snapshot available; target-only hold operation has no non-target update path"}
        backup = sqlite3.connect(backup_path)
        backup.row_factory = sqlite3.Row
        columns = ["application_id", "contractor_id", "canonical_sov_item_id", "claim_number",
                   "claimed_amount_cents", "claim_status", "certification_status",
                   "low_value_consumable_flag", "incorporated_into_completed_work_flag",
                   "submitter_id", "submitter_name", "submitted_at", "source_system", "created_at"]
        current_rows = connection.execute(
            "SELECT material_claim_id, " + ", ".join(columns) + " FROM material_claims WHERE material_claim_id <> ? ORDER BY material_claim_id",
            (TARGET,),
        ).fetchall()
        baseline_rows = backup.execute(
            "SELECT material_claim_id, " + ", ".join(columns) + " FROM material_claims WHERE material_claim_id <> ? ORDER BY material_claim_id",
            (TARGET,),
        ).fetchall()
        baseline = {row["material_claim_id"]: tuple(row[column] for column in columns) for row in baseline_rows}
        for row in current_rows:
            if row["material_claim_id"] in baseline and tuple(row[column] for column in columns) != baseline[row["material_claim_id"]]:
                return {"score": 0, "detail": f"non-target claim changed: {row['material_claim_id']}"}
        if len(current_rows) < len(baseline_rows):
            return {"score": 0, "detail": "a non-target claim was removed"}
        return {"score": 1, "detail": "no baseline-mapped non-target claim changed"}
    finally:
        connection.close()
        if backup is not None:
            backup.close()
